var motionDetect = "Sensor.MotionDetect";
var motionSensor = hg.modules.inDomain("HomeAutomation.Demo").withAddress("1").get();
//var currentValue = motion.parameter(motionDetect).decimalValue;
motionSensor.emit(motionDetect, "1");
hg.pause(1);
motionSensor.emit(motionDetect, "0");

var doorWindow = "Sensor.DoorWindow";
var doorSensor = hg.modules.inDomain("HomeAutomation.Demo").withAddress("2").get();
var currentValue = doorSensor.parameter(doorWindow).decimalValue;
doorSensor.emit(doorWindow, currentValue == 0 ? "1" : "0", "");

/*
|| @title: Sensor Simulator
|| @author: Generoso Martello
|| @version: 1.0
|| @updated: 2019-01-01 01:01
|| @licence: https://raw.githubusercontent.com/genielabs/HomeGenie/master/LICENSE_GPLV3.TXT
||
|| HomeGenie API reference
||   https://homegenie.it/content/devs/programs/
||   https://homegenie.it/api/ape/annotated.html
||   https://homegenie.it/api/mig/overview.html
*/

const string TEMPERATURE_FIELD = "Sensor.Temperature";
const string LUMINANCE_FIELD = "Sensor.Luminance";
const string HUMIDITY_FIELD = "Sensor.Humidity";
const string WATER_LEVEL_FIELD = "Sensor.WaterLevel";
const string WATTS_FIELD = "Meter.Watts";
const string EMIT_FREQUENCY_FIELD = "Simulator.Sensor.DataFrequency";

while (Program.IsRunning) {
  Pause(0.25);
  var now = DateTime.Now;

  foreach (var sensorType in new[] { TEMPERATURE_FIELD, HUMIDITY_FIELD, LUMINANCE_FIELD, WATER_LEVEL_FIELD }) {
    var fieldName = sensorType;
    Modules.WithFeature("Simulator." + fieldName).Each(module => {
      var frequency = module.Parameter(EMIT_FREQUENCY_FIELD);
      var field = module.Parameter(fieldName);
      if (frequency.DecimalValue > 0 && field.IdleTime >= frequency.DecimalValue) {
        string sensorId = module.Instance.Domain + ":" + module.Instance.Address;
        module.Emit(fieldName, GetSensorValue(now, fieldName, sensorId));
      }
      return false;
    });
  }

  // Emit zero regularly too: historical averages must include switched-off time.
  Modules.WithFeature("Simulator." + WATTS_FIELD).Each(module => {
    var frequency = module.Parameter(EMIT_FREQUENCY_FIELD);
    var powerMax = module.Parameter("Simulator." + WATTS_FIELD + ".Max");
    var level = module.Parameter("Status.Level");
    var field = module.Parameter(WATTS_FIELD);
    if (frequency.DecimalValue > 0 && field.IdleTime >= frequency.DecimalValue && powerMax.DecimalValue > 0) {
      module.Emit(WATTS_FIELD, GetPowerValue(powerMax.DecimalValue, level != null ? level.DecimalValue : 0));
    }
    return false;
  });
}

ProgramBlock.ScriptContext:
// Generic indoor demo profile for a temperate northern-hemisphere climate.
// This is illustrative data, not weather, astronomy or a model of a real building.
// Calendar time (including minutes/seconds) keeps values continuous across emits.
static double GetSensorValue(DateTime localTime, string sensorType, string sensorId = "")
{
    uint hash = 2166136261;
    foreach (char c in sensorId ?? "") hash = unchecked((hash ^ c) * 16777619);
    double phase = (hash % 10000) / 10000.0 * Math.PI * 2;
    double offset = ((hash >> 16) / 65535.0 - 0.5) * 2;
    double hour = localTime.TimeOfDay.TotalHours;
    double yearDays = DateTime.IsLeapYear(localTime.Year) ? 366 : 365;
    double year = (localTime.DayOfYear - 1 + hour / 24) / yearDays;
    double season = Math.Cos(2 * Math.PI * (year - 0.55)); // warmest in July
    double daily = Math.Cos(2 * Math.PI * (hour - 15) / 24);
    double days = (localTime - new DateTime(2000, 1, 1)).TotalDays;
    double weather = Math.Sin(2 * Math.PI * days / 5.7);
    double detail = Math.Sin(2 * Math.PI * days * 24 / 2.8 + phase);

    switch ((sensorType ?? "").Trim().ToLowerInvariant())
    {
        case "temperature":
        case "sensor.temperature":
            return Math.Round(Math.Clamp(22 + 3.5 * season + daily + 0.6 * weather + 0.5 * offset + 0.08 * detail, 16, 29), 2);
        case "humidity":
        case "sensor.humidity":
            return Math.Round(Math.Clamp(50 - 5 * season - 4 * daily - 2 * weather + 2 * offset + 0.3 * detail, 35, 65), 2);
        case "luminance":
        case "sensor.luminance":
            // A 48-minute ambient cycle keeps demo charts moving after dark.
            double nightLux = 50 * (1 + Math.Sin(2 * Math.PI * hour / 0.8 + phase));
            double daylightHours = 12 + 3 * Math.Cos(2 * Math.PI * (year - 0.47));
            double sunrise = 12 - daylightHours / 2;
            double daylight = (hour - sunrise) / daylightHours;
            if (daylight <= 0 || daylight >= 1) return Math.Round(nightLux);
            double daylightFactor = Math.Pow(Math.Sin(Math.PI * daylight), 1.5);
            double peak = (600 + 200 * season + 50 * weather + 35 * offset) * (1 + 0.02 * detail);
            return Math.Round(Math.Clamp(nightLux + (peak - nightLux) * daylightFactor, 0, 1000));
        case "sensor.waterlevel":
            // A short fill and drain cycle makes the demo visible without waiting hours.
            double fillCycle = Math.Sin(2 * Math.PI * localTime.TimeOfDay.TotalMinutes / 12 + phase);
            return Math.Round(50 + 40 * fillCycle, 1);
        default:
            throw new ArgumentException("Unsupported simulated sensor: " + sensorType, nameof(sensorType));
    }
}

// Power remains tied to device state, rather than time of day or season.
static double GetPowerValue(double maximumWatts, double level)
{
    if (!double.IsFinite(maximumWatts) || maximumWatts <= 0 || !double.IsFinite(level)) return 0;
    return Math.Round(maximumWatts * Math.Clamp(level, 0, 1), 2);
}

ProgramBlock.ScriptSetup:
// Add "Emulate UPnP device" feature
Program.AddFeature(
    description:
    // Description of this feature
    "Emulate UPnP device (WeMo)",
    parameterName:
    // Name of the module's parameter where to store this feature data
    "UpnpDevice.EmulateWemo",
    type:
    // Display in the UI as a checkbox
    "checkbox",
    forDomains:
    // Show this feature for all domains
    "",
    forModuleTypes:
    // Show this feature for all module types
    "Switch,Light,Dimmer"
);
// Run the 'Program Code'
Program.Run();

ProgramBlock.ScriptSource:
var FEATURE_EMULATE_WEMO = "UpnpDevice.EmulateWemo";
var PARAM_UPNP_INFO_UDN = "UpnpDevice.Info.UDN";
// List that holds allocated UPnP devices
var upnpDevices = new Dictionary<Module, UPnPDevice>();

Func<ModuleHelper, UPnPDevice> createUpnpModule = (module) =>
{
    // Create the UPnP device to control the 'module'
    var upnpDevice = UPnPDevice.CreateRootDevice(3600, 1, null);
    // use the same ID even when restarted
    if (module.HasParameter(PARAM_UPNP_INFO_UDN))
    {
        upnpDevice.UniqueDeviceName = module.Parameter(PARAM_UPNP_INFO_UDN).Value;
    }
    else
    {
        module.Parameter(PARAM_UPNP_INFO_UDN).Value = upnpDevice.UniqueDeviceName;
    }
    upnpDevice.ModelNumber = "3.1234";
    // Socket, Lightswitch - TODO: Insight, Motion
    var modelName = "";
    if (
        module.Instance.DeviceType == ModuleTypes.Light
        || module.Instance.DeviceType == ModuleTypes.Dimmer
    )
    {
        modelName = "Lightswitch";
        upnpDevice.StandardDeviceType = "urn:Belkin:device:lightswitch";
        upnpDevice.ModelDescription = "Belkin Light Switch 1.0";
    }
    else
    {
        modelName = "Socket";
        upnpDevice.StandardDeviceType = "urn:Belkin:device:controllee";
        upnpDevice.ModelDescription = "Belkin Plugin Socket 1.0";
    }
    upnpDevice.ModelName = modelName;
    // Prepend modelName (device type) to the UDN
    upnpDevice.UniqueDeviceName = modelName + "-" + upnpDevice.UniqueDeviceName;
    upnpDevice.FriendlyName = module.Instance.Name;
    upnpDevice.Manufacturer = "Belkin International Inc.";
    upnpDevice.ManufacturerURL = "http://www.belkin.com";
    upnpDevice.Major = 1;
    upnpDevice.Minor = 0;
    upnpDevice.SerialNumber = "EMU-1234567890";
    upnpDevice.UserAgentTag = "redsonic";

    // Create an instance of the BasicEvent service
    dynamic instance = new ExpandoObject();

    // Declare the "BasicEvent1" service
    var service = new UPnPService(
        // Version
        1.0,
        // Service ID
        "urn:Belkin:serviceId:basicevent1",
        // Service Type
        "urn:Belkin:service:basicevent:1",
        // Standard Service?
        true,
        // Service Object Instance
        instance
    );
    service.ControlURL = "/upnp/control/basicevent1";
    service.EventURL = "/upnp/event/basicevent1";
    service.SCPDURL = "/eventservice.xml";

    string stateVarName = "BinaryState";
    var stateVariable = new UPnPStateVariable(stateVarName, typeof(bool), true);
    stateVariable.AddAssociation("GetBinaryState", stateVarName);
    stateVariable.AddAssociation("SetBinaryState", stateVarName);
    stateVariable.Value = false;
    service.AddStateVariable(stateVariable);

    instance.GetBinaryState = new Func<bool>(
        () => (bool)service.GetStateVariable(stateVarName) /* module.IsOn */
    );
    instance.SetBinaryState = new Action<int>(
        (BinaryState) =>
        {
            service.SetStateVariable(stateVarName, BinaryState != 0);
            if (BinaryState == 1)
                module.On();
            else
                module.Off();
        }
    );

    // Add the methods
    service.AddMethod("GetBinaryState", stateVarName);
    service.AddMethod("SetBinaryState", stateVarName);

    // Add the service
    upnpDevice.AddService(service);
    // Start the WeMo switch device UPnP simulator
    upnpDevice.StartDevice();

    return upnpDevice;
};


When.ModuleParameterChanged(
    (m, p) =>
    {
        // The checkbox option "UpnpDevice.EmulateWemo" has been changed
        if (p.Is(FEATURE_EMULATE_WEMO))
        {
            // Remove the UPnP device if already allocated
            if (upnpDevices.ContainsKey(m.Instance))
            {
                upnpDevices[m.Instance].StopDevice();
                upnpDevices.Remove(m.Instance);
                Program.Notify("Removed UPnP device for {0}", m.Instance.Name);
            }
            // Check if the option is ON (not empty = On)
            if (!String.IsNullOrEmpty(p.Value))
            {
                Program.Notify("Added UPnP device for {0}", m.Instance.Name);
                upnpDevices.Add(m.Instance, createUpnpModule(m));
            }
        }
        else if (upnpDevices.ContainsKey(m.Instance) && p.Is("Status.Level"))
        {
            // Update status level of the associated UPnP device
            upnpDevices[m.Instance].Services[0].SetStateVariable(
                "BinaryState",
                (p.DecimalValue != 0)
            );
        }
        return true;
    }
);


When.ProgramStopping(
    () =>
    {
        // Stop allocated UPnP devices
        foreach (var upnp in upnpDevices.Values)
        {
            Program.Notify("Removed UPnP device for {0}", upnp.FriendlyName);
            upnp.StopDevice();
        }
        return true;
    }
);


// Allocates UPnP devices for modules with this option active
Modules
    .WithFeature(FEATURE_EMULATE_WEMO)
    .Each(
        (m) =>
        {
            upnpDevices.Add(m.Instance, createUpnpModule(m));
            return false; // continue iterating
        }
    );


// Continue running the program in the background
Program.GoBackground();

ProgramBlock.ScriptSetup:
/*
|| @title: Virtual Modules Demo App
|| @author: Generoso Martello
|| @version: 1.1
|| @updated: 2025-04-08 19:28
|| @version: 1.0
|| @updated: 2016-04-30 16:54
|| @licence: https://raw.githubusercontent.com/genielabs/HomeGenie/master/LICENSE_GPLV3.TXT
||
|| HomeGenie API reference
||   https://homegenie.it/content/devs/programs/
||   https://homegenie.it/api/ape/annotated.html
||   https://homegenie.it/api/mig/overview.html
*/

const domain = "HomeAutomation.Demo";
const type = {
  Sensor: "Sensor",
  DoorWindow: "DoorWindow",
  Switch: "Switch",
  Shutter: "Shutter"
};

// Add a temperature and luminance sensor
hg.program
  .addModule(domain, "1", type.Sensor);

// Add a doorwindow sensor
hg.program
  .addModule(domain, "2", type.DoorWindow);

// Add an on/off switch
hg.program
  .addModule(domain, "3", type.Switch);

// Add two shutters
hg.program
  .addModule(domain, "4", type.Shutter)
  .addModule(domain, "5", type.Shutter);

// Add the demo water tank sensor
hg.program.addModule(domain, "6", type.Sensor);

hg.program.run();

ProgramBlock.ScriptSource:
/*
|| @title: Virtual Modules Demo App
|| @author: Generoso Martello
|| @version: 1.1
|| @updated: 2025-04-08 19:28
|| @version: 1.0
|| @updated: 2016-04-30 16:54
|| @licence: https://raw.githubusercontent.com/genielabs/HomeGenie/master/LICENSE_GPLV3.TXT
||
|| HomeGenie API reference
||   https://homegenie.it/content/devs/programs/
||   https://homegenie.it/api/ape/annotated.html
||   https://homegenie.it/api/mig/overview.html
*/

const domain = "HomeAutomation.Demo";
const demoModules = hg.modules.inDomain(domain);

initialize();

// handle API call for this domain
hg.api.handle(domain, function(apiCall) {

  const ac = hg.api.parse(apiCall);
  // Example:
  //  if the "apiCall" is
  //    "http://<homegenie_address>/api/HomeAutomation.Demo/3/Control.Level/50/1000"
  //  then "ac" will have the following property values
  //    ac.domain = "HomeAutomation.Demo"
  //    ac.address = "3"
  //    ac.command = "Control.Level"
  //    ac.optionsString = "50/1000"
  //    ac.getOption(0) = "50"
  //    ac.getOption(1) = "1000"

  let response = "ERROR";
  // get the module addressed by the API call
  const mod = demoModules.withAddress(ac.address).get();
  if (mod.Instance.Domain === domain) {
    switch (ac.command) {
      case 'Control.On':
      case 'Control.Open':
        mod.emit("Status.Level", 1);
        response = "OK";
        break;
      case 'Control.Off':
      case 'Control.Close':
        mod.emit("Status.Level", 0);
        response = "OK";
        break;
      case 'Control.Toggle':
        mod.emit("Status.Level", mod.level != 0 ? 0 : 1);
        response = "OK";
        break;
      case 'Control.Level':
        mod.emit("Status.Level", ac.getOption(0)/100);
        response = "OK";
        break;
    }
  }

  // beside the response, also return back requested data for debugging purpose
  return {
    ResponseValue: response,
    ApiCall: apiCall,
    Domain: ac.domain,
    Address: ac.address,
    Command: ac.command,
    Options: ac.optionsString,
    Option1: ac.getOption(0),
    Option2: ac.getOption(1)
  };

});

hg.program.goBackground();

// let's give some default properties to virtual modules
function initialize() {
  // Multi Sensor
  const multiSensor = demoModules.withAddress("1").get();
  if (multiSensor.instance.name == "") {
    multiSensor.instance.name = 'Multi Sensor';
  }
  const temperature = multiSensor.parameter("Sensor.Temperature");
  if (temperature.value == "") {
    temperature.value = 25.5;
  }
  const luminance = multiSensor.parameter("Sensor.Luminance");
  if (luminance.value == "") {
    luminance.value = 273;
  }
  const motionDetect = multiSensor.parameter("Sensor.MotionDetect");
  if (motionDetect.value == "") {
    motionDetect.value = 0;
  }
  // Water tank
  const tank = demoModules.withAddress("6").get();
  if (tank.instance.name == "") {
    tank.instance.name = "Water Tank Sensor";
  }
  if (tank.parameter("Sensor.WaterLevel").value == "") {
    tank.parameter("Simulator.Sensor.WaterLevel").value = "On";
    tank.parameter("Simulator.Sensor.DataFrequency").value = 5;
    tank.emit("Sensor.WaterLevel", 50);
  }
  // Door Window
  const doorWindow = demoModules.withAddress("2").get();
  if (doorWindow.instance.name == "") {
    doorWindow.instance.name = "Door Sensor";
  }
  const sensorDoorWindow = doorWindow.parameter("Sensor.DoorWindow");
  if (sensorDoorWindow.value == "") {
    sensorDoorWindow.value = 1;
  }
  // Boiler Switch
  const boilerSwitch = demoModules.withAddress("3").get();
  if (boilerSwitch.instance.name == "") {
    boilerSwitch.instance.name = "Boiler Switch";
  }
  const statusLevel = boilerSwitch.parameter("Status.Level");
  if (statusLevel.value == "") {
    statusLevel.value = 0;
  }
  // Window Shutter 1
  const shutter1 = demoModules.withAddress("4").get();
  if (shutter1.instance.name == "") {
    shutter1.instance.name = "Window Shutter 1";
  }
  const statusLevelShutter1 = shutter1.parameter("Status.Level");
  if (statusLevelShutter1.value == "") {
    statusLevelShutter1.value = 0; // 0 = Closed, 100 = Open
  }
  const batteryShutter1 = shutter1.parameter("Status.Battery");
  if (batteryShutter1.value == "") {
    batteryShutter1.value = 95;
  }
  // Window Shutter 2
  const shutter2 = demoModules.withAddress("5").get();
  if (shutter2.instance.name == "") {
    shutter2.instance.name = "Window Shutter 2";
  }
  const statusLevelShutter2 = shutter2.parameter("Status.Level");
  if (statusLevelShutter2.value == "") {
    statusLevelShutter2.value = 0.5;
  }
  const batteryShutter2 = shutter2.parameter("Status.Battery");
  if (batteryShutter2.value == "") {
    batteryShutter2.value = 42;
  }
}
